import{minute17Defaults as defaults,minute17Scenes as scenes,minute17Assets as assets,preloadMinute17,paintMinute17,validateMinute17,getMinute17Metadata,minute17EffectLibrary}from'./minute17-sequence.js';
const $=id=>document.getElementById(id),canvas=$('stage'),ctx=canvas.getContext('2d');let cfg=structuredClone(defaults),time=0,playing=false,last=0,media={};
function draw(){const out=paintMinute17(ctx,time,media,cfg),t=out.masterSecond;$('time').textContent=`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}.${String(Math.floor(t%1*100)).padStart(2,'0')}`;$('scrub').value=time}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function control(host,label,obj,key,min,max,step){const lab=document.createElement('label');lab.append(label);const input=document.createElement('input');input.type='number';input.setAttribute('aria-label',label);Object.assign(input,{min,max,step,value:obj[key]});input.onchange=()=>{const prev=obj[key];try{obj[key]=Number(input.value);if(obj[key]<min||obj[key]>max)throw Error('Outside control range');validateMinute17(cfg);$('status').textContent='Updated '+label;draw()}catch(e){obj[key]=prev;input.value=prev;$('status').textContent=e.message}};lab.append(input);host.append(lab)}
function globals(){const host=$('controls');host.replaceChildren();for(const [name,key,min,max,step]of [['Portrait separation','portraitGap',0,180,2],['Portrait final size','portraitEndWidth',160,300,2],['Hair wind','hairWind',0,4,.1],['Hair wind speed','hairSpeed',.1,3,.1],['Heat shimmer','heat',0,3,.1],['Ground mist','groundSmoke',0,2,.05],['Distant lights','lightDepth',0,2,.05],['Side light streak','lightBeam',0,2,.05],['Panel pullback','panelPullback',0,.2,.01],['Pullback begins','panelPullbackStart',15,20,.1],['Pullback finishes','panelPullbackEnd',21,25,.1],['Panel smoky light','panelSmoke',0,2,.05],['Photo edge wear','photoWear',0,1,.05],['Photo emulsion age','photoAge',0,1,.05],['Photo grain','photoGrain',0,.3,.01],['Speed','speed',.1,3,.05],['Zoom','zoom',.5,2,.01],['Depth motion','parallax',0,3,.1],['Rain density','rain',0,3,.1],['Rain speed','rainSpeed',-2,2,.05],['Fog opacity','fog',0,.5,.01],['Glow','glow',0,50,1],['Reflection','reflection',0,.7,.01],['Products start','productStart',3,10,.1],['Product stagger','productStagger',0,.6,.05],['Red panel start','panelRedStart',10,15,.1],['Blue panel start','panelBlueStart',10,15,.1],['Panel rise duration','panelRise',.3,4,.1],['Panels part at','panelExit',23,28,.1],['Panels clear at','panelExitEnd',24,30,.1],['Photo starting width','photoStartWidth',200,900,10],['Photo ending width','photoEndWidth',150,800,10],['Photo retreat','photoRetreat',0,1,.05],['Split starts at','splitStart',32,37,.1],['Split duration','splitDuration',1,5,.1],['Split distance','splitGap',0,340,5],['Split angle','splitTilt',-80,80,1],['Flare strength','flare',0,3,.05],['Flare duration','flareDuration',.4,4,.1]])control(host,name,cfg,key,min,max,step);$('title').value=cfg.bridgeTitle;$('subtitle').value=cfg.bridgeSubtitle;$('reverse').textContent='Reverse: '+(cfg.reverse?'on':'off')}
function layerControls(){const id=$('layer').value,l=cfg.layers[id],host=$('layerControls');host.replaceChildren();for(const [name,key,min,max,step]of [['Position X','x',-600,600,1],['Position Y','y',-500,500,1],['Layer size','scale',.1,3,.01],['Rotation','rotation',-180,180,1],['Opacity','opacity',0,1,.01],['Blur','blur',0,20,.1],['Layer depth','depth',0,4,.1]])control(host,name,l,key,min,max,step);const lab=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=l.visible;ch.onchange=()=>{l.visible=ch.checked;draw()};lab.append('Visible',ch);host.append(lab);const a=getMinute17Metadata().assets.find(a=>a.file.endsWith('/'+assets[id]));$('tag').textContent=cfg.mediaBindings?.[id]?'USER REPLACEMENT · provenance unverified':a?.archival?'ARCHIVAL IMAGE · animated framed panel':'ILLUSTRATION / GRAPHIC';$('metadata').textContent=JSON.stringify(cfg.mediaBindings?.[id]?{kind:'user-replacement',archival:false,filename:cfg.mediaNames?.[id],retains:'existing layer animation'}:a,null,2)}
$('scene').append(...scenes.map(s=>new Option(s.label,s.start)));$('scene').onchange=()=>{time=+$('scene').value+.02;playing=false;draw()};$('layer').append(...Object.keys(assets).map(id=>new Option(id,id)));$('layer').value='photo';$('layer').onchange=layerControls;
$('scrub').oninput=e=>{time=+e.target.value;playing=false;$('play').textContent='Play';draw()};$('play').onclick=()=>{playing=!playing;if(time>=60)time=0;$('play').textContent=playing?'Pause':'Play';last=0};$('reverse').onclick=()=>{cfg.reverse=!cfg.reverse;globals();draw()};
$('save').onclick=()=>{validateMinute17(cfg);download(new Blob([JSON.stringify(cfg,null,2)],{type:'application/json'}),'regaarder-minute17-v125-preset.json')};$('load').onclick=()=>$('preset').click();
async function decodeBindings(v){const m={};for(const[id,data]of Object.entries(v.mediaBindings||{})){if(!assets[id]||typeof data!=='string'||!/^data:image\/(png|jpeg|webp|gif);base64,/.test(data))throw Error('Unsupported media binding');const im=new Image();im.src=data;await im.decode();m[id]=im}return m}
$('preset').onchange=async e=>{try{const loaded=JSON.parse(await e.target.files[0].text()),v={...structuredClone(defaults),...loaded,layers:{...structuredClone(defaults.layers),...loaded.layers}};validateMinute17(v);const next=await decodeBindings(v);cfg=v;media=next;globals();layerControls();draw();$('status').textContent='Preset and media restored'}catch(e){$('status').textContent='Import failed: '+e.message}};
$('replace').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});const id=$('layer').value,im=new Image();im.src=data;await im.decode();media[id]=im;cfg.mediaBindings??={};cfg.mediaBindings[id]=data;cfg.mediaNames??={};cfg.mediaNames[id]=file.name;layerControls();draw();$('status').textContent='Image replaced; save preset to retain it.'}catch(e){$('status').textContent=e.message}};
$('reset').onclick=()=>{cfg=structuredClone(defaults);media={};globals();layerControls();draw()};$('frame').onclick=()=>canvas.toBlob(b=>download(b,'minute17-frame.png'));
$('title').onchange=e=>{cfg.bridgeTitle=e.target.value;draw()};$('subtitle').onchange=e=>{cfg.bridgeSubtitle=e.target.value;draw()};$('effects').textContent=JSON.stringify(minute17EffectLibrary,null,2);
window.minute17Editor={get config(){return cfg},get media(){return media},paint(t){time=t;draw()},canvas};
await preloadMinute17();globals();layerControls();draw();$('status').textContent='Ready · 19 image bindings · editable archival photo';window.minute17Ready=true;
function tick(now){if(playing){if(last)time=Math.min(60,time+(now-last)/1000);draw();if(time>=60){playing=false;$('play').textContent='Play'}}last=now;requestAnimationFrame(tick)}requestAnimationFrame(tick);
